package sfz.batch.l07.demo

import org.apache.spark.sql.Row
import org.apache.spark.sql.functions.col
import java.io.DataInputStream
import java.io.File

/**
 * Shuffles 1,000,000 payments by merchant_id into 4 partitions, then lists the shuffle files the
 * 4 map tasks left in spark.local.dir and decodes one index file by hand.
 */
fun main() {
    val local = File("build/l06/local").apply { deleteRecursively(); mkdirs() }
    val spark = demoSpark(localDir = local)
    val log = StageLog(spark)
    val byMerchant = payments(spark).repartition(4, col("merchant_id"))
    // the action: every reduce task reads its whole partition and throws the rows away
    val (_, stages) = log.run { byMerchant.foreachPartition { rows: Iterator<Row> -> rows.forEach { _ -> } } }
    for (s in stages) {
        println("stage %d: %d tasks, shuffle write %,d records / %,d bytes, shuffle read %,d bytes".format(
            s.id, s.tasks, s.recordsWritten, s.bytesWritten, s.bytesRead))
    }
    val files = local.walkTopDown().filter { it.isFile && it.name.startsWith("shuffle_") }.sortedBy { it.name }.toList()
    println("files in spark.local.dir (blockmgr-.../xx/):")
    files.filter { !it.name.contains("checksum") }.forEach { println("  %-24s %,10d bytes".format(it.name, it.length())) }
    // an index file is N + 1 longs: where each reduce partition's block starts in the .data file
    val index = files.first { it.name.endsWith(".index") }
    val offsets = DataInputStream(index.inputStream()).use { d -> List((index.length() / 8).toInt()) { d.readLong() } }
    println("${index.name}: offsets $offsets")
    println("  so reduce task r fetches bytes offsets[r] until offsets[r + 1] of ${index.name.replace(".index", ".data")}")
    spark.stop()
}

package sfz.batch.l07.demo

import org.apache.spark.sql.functions.sum

/**
 * The same groupBy over 1,000,000 payments with spark.sql.shuffle.partitions set to 4, 200 and
 * 2,000 (AQE off), and then 2,000 with AQE on. Prints the tasks each run needed and its time.
 */
fun main() {
    val spark = demoSpark()
    val log = StageLog(spark)
    val p = payments(spark).cache()
    p.count()                                                     // read once into memory, so runs compare the shuffle only
    for ((partitions, aqe) in listOf(4 to false, 200 to false, 2000 to false, 2000 to true)) {
        spark.conf().set("spark.sql.shuffle.partitions", partitions.toString())
        spark.conf().set("spark.sql.adaptive.enabled", aqe.toString())
        // a new DataFrame for every run: running the same one again would reuse its shuffle files
        fun totals() = p.groupBy("merchant_id").agg(sum("amount_cents"))
        totals().collectAsList()                                  // warm-up
        val times = (1..3).map {
            val df = totals()
            val t0 = System.nanoTime()
            df.collectAsList()
            (System.nanoTime() - t0) / 1e6
        }
        val (_, stages) = log.run { totals().collectAsList() }
        println("shuffle.partitions=%-5d AQE %-3s -> tasks per stage %-10s shuffled %,d rows (%,d bytes), best of 3: %4.0f ms".format(
            partitions, if (aqe) "on" else "off", stages.map { it.tasks }, stages.sumOf { it.recordsWritten },
            stages.sumOf { it.bytesWritten }, times.min()))
    }
    spark.stop()
}

package sfz.batch.l07.demo

import org.apache.spark.sql.Dataset
import org.apache.spark.sql.Row
import org.apache.spark.sql.functions.broadcast
import org.apache.spark.sql.functions.sum

/**
 * Joins 1,000,000 payments with 500 merchants three ways and prints, for each, the join node in
 * the plan, what the scheduler ran, the shuffle traffic and the time.
 */
fun main() {
    val spark = demoSpark()
    val log = StageLog(spark)
    val payments = payments(spark)
    val merchants = merchants(spark)
    fun query(join: Dataset<Row>) = join.groupBy("merchant_name").agg(sum("amount_cents").alias("total"))
    val cases = listOf(
        "broadcast (default, merchants < 10 MB)" to { query(payments.join(merchants, "merchant_id")) },
        "sort-merge (broadcasting turned off)" to {
            spark.conf().set("spark.sql.autoBroadcastJoinThreshold", "-1")
            query(payments.join(merchants, "merchant_id"))
        },
        "shuffled hash (SHUFFLE_HASH hint)" to { query(payments.join(merchants.hint("shuffle_hash"), "merchant_id")) },
        "broadcast hint, threshold still off" to { query(payments.join(broadcast(merchants), "merchant_id")) },
    )
    for ((label, build) in cases) {
        // a new DataFrame for every run: running the same one again would reuse its shuffle files
        build().collectAsList()                                    // warm-up
        val best = (1..3).minOf {
            val df = build()
            val t0 = System.nanoTime()
            df.collectAsList()
            (System.nanoTime() - t0) / 1e6
        }
        val df = build()
        val (jobs, stages) = log.run { df.collectAsList() }
        println(label)
        planLines(df, "Join", "Exchange").forEach { println("  $it") }
        println("  ran: %d job(s), tasks per stage %s, shuffle wrote %,d records (%,d bytes), best of 3: %.0f ms".format(
            jobs.size, stages.map { it.tasks }, stages.sumOf { it.recordsWritten }, stages.sumOf { it.bytesWritten }, best))
    }
    spark.stop()
}

